INSERT INTO `products` VALUES ('161', 'High Pro Cordero Razas Pequeñas', 'high-pro-cordero-razas-pequenas-7-5kg', 'High Pro Criadores', 'perro', 'adulto', 'pequeña', 'super_premium', '7.50', '33900.00', '30510.00', NULL, '25', 'https://baires-sa.com.ar/img_productos/Render%20High%20Pro%20Cordero%20Razas%20pequenas.png', 'https://baires-sa.com.ar/img_productos/Tablacomposicionpequeno.jpg', 'Fórmula exclusiva de cordero para perros adultos de mandíbula pequeña y metabolismo acelerado. Croqueta mini de fácil masticación y alta densidad calórica equilibrada.\n\nBeneficios destacados:\n• Croqueta mini con efecto mecánico antisarro\n• Proteína novel de cordero para reducir alergias alimentarias\n• Omega 3 y 6 para pelaje sedoso y piel sin descamación\n\nIngredientes completos:\nHarina de cordero, arroz, gluten de maíz, germen de maíz desgrasado, aceite de pollo, aceite de pescado (fuente de omega 3), hidrolizado proteico de pollo, pulpa de remolacha, levadura de cerveza, hexametafosfato de sodio, extracto de yucca schidigera, vitaminas y minerales.', '0', '2026-11-04 23:32:38', '0', '0', NULL, NULL);
INSERT INTO `products` VALUES ('160', 'High Pro Cordero Cachorros', 'high-pro-cordero-cachorros-15kg', 'High Pro Criadores', 'perro', 'cachorro', 'todas', 'super_premium', '15.00', '52900.00', '47610.00', NULL, '18', 'https://baires-sa.com.ar/img_productos/Render%20High%20Pro%20Cordero%20Cachorros.png', 'https://baires-sa.com.ar/img_productos/Tablacomposicioncachorro.jpg', 'Nutrición avanzada con proteína de cordero para cachorros en fase de crecimiento temprano. Proporciona máxima tolerancia digestiva y desarrollo armónico del sistema óseo, muscular e inmunológico.\n\nBeneficios destacados:\n• 27% de proteína con cordero como ingrediente destacado\n• DHA y ácidos grasos Omega 3 para óptimo desarrollo cerebral\n• Nucleótidos y prebióticos para reforzar el sistema inmunológico\n\nIngredientes completos:\nHarina de cordero, arroz, gluten de maíz, germen de maíz desgrasado, aceite de pollo, aceite de pescado (fuente de omega 3), hidrolizado proteico de pollo, huevo entero en polvo, pulpa de remolacha, levadura de cerveza, nucleótidos, extracto de yucca schidigera, vitaminas y minerales orgánicos.', '0', '2026-11-04 23:32:38', '0', '0', NULL, NULL);
INSERT INTO `products` VALUES ('159', 'High Pro Cordero Perros Adultos', 'high-pro-cordero-perros-adultos-15kg', 'High Pro Criadores', 'perro', 'adulto', 'mediana_grande', 'super_premium', '15.00', '49900.00', '44910.00', NULL, '22', 'https://baires-sa.com.ar/img_productos/Render%20High%20Pro%20Cordero%20Adultos.png', 'https://baires-sa.com.ar/img_productos/Tablacomposicionadulto.jpg', 'Alimento super premium formulado con harina de cordero como principal fuente proteica novel hipoalergénica. Especialmente desarrollado para perros adultos con digestión delicada o sensibilidad dérmica.\n\nBeneficios destacados:\n• Mono-proteína animal de cordero de altísima asimilación\n• Arroz integral no transgénico como fuente noble de carbohidratos\n• Glucosamina y condroitina para nutrición articular continua\n\nIngredientes completos:\nHarina de cordero, arroz, gluten de maíz, germen de maíz desgrasado, aceite de pollo, aceite de pescado (fuente de omega 3), hidrolizado proteico de pollo, pulpa de remolacha, levadura de cerveza, zeolita, glucosamina, sulfato de condroitina, extracto de yucca schidigera, antioxidantes naturales, vitaminas y minerales.', '1', '2026-11-04 23:32:38', '1', '0', NULL, 'Fórmula Novel Hipoalergénica con Cordero Puro');
INSERT INTO `products` VALUES ('158', 'High Pro Criadores Gatos Adultos', 'high-pro-criadores-gatos-adultos-7-5kg', 'High Pro Criadores', 'gato', 'adulto', 'todas', 'premium', '7.50', '38900.00', '35010.00', NULL, '20', 'https://baires-sa.com.ar/img_productos/Render%20High%20Pro%20Gato%20Adulto.png', 'https://baires-sa.com.ar/img_productos/Centecimalgatohighpro.jpg', 'Nutrición balanceada de alto rendimiento formulada específicamente para gatos adultos por Baires S.A. Control riguroso de pH urinario, taurina esencial para la función cardíaca y visual, y combinación de proteínas nobles de salmón y pollo.\n\nBeneficios destacados:\n• 32% de proteína bruta para mantenimiento de masa muscular activa\n• Hairball control y protección integral de vías urinarias inferiores\n• Enriquecido con taurina, metionina y ácidos grasos esenciales\n\nIngredientes completos:\nHarina de salmón, harina de pescado, harina de pollo, arroz, maíz, gluten de maíz, arveja, aceite de pollo, aceite de pescado (fuente de omega 3 y 6), hidrolizado de menudencias porcinas y aviares, levadura de cerveza, pulpa de remolacha, bisulfato de sodio, taurina, L-carnitina, metionina, lisina, extracto de yucca schidigera, vitaminas y minerales quelados.', '0', '2026-11-04 23:32:38', '0', '0', NULL, NULL);
INSERT INTO `products` VALUES ('157', 'High Pro Criadores Perros Adultos', 'high-pro-criadores-perros-adultos-22kg', 'High Pro Criadores', 'perro', 'adulto', 'todas', 'premium', '22.00', '54900.00', '49410.00', NULL, '25', 'https://baires-sa.com.ar/img_productos/renderadultohighpro.png', 'https://baires-sa.com.ar/img_productos/12181749_HighProTabla.jpg', 'Alimento completo y balanceado de alta performance formulado por Baires S.A. para criadores y perros adultos de todas las razas con alta exigencia física. Aporte energético equilibrado, proteínas de alto valor biológico y óptima digestibilidad.\n\nBeneficios destacados:\n• 23% de proteína bruta y alta digestibilidad para masa muscular magra\n• Extracto de Yucca schidigera para reducción comprobada de olores en heces\n• Ácidos grasos Omega 3 y 6 para pelaje brillante y piel sana\n\nIngredientes completos:\nHarina de pollo, harina de carne, arveja, trigo, maíz, germen de maíz, gluten de maíz, harina de soja, aceite de pollo, aceite de pescado (fuente de omega 3 y 6), hidrolizado proteico de pollo, levadura de cerveza, pulpa de remolacha, extracto de yucca schidigera, ácido propiónico, BHT, BHA, vitaminas (A, D3, E, K, B1, B2, B6, B12), ácido fólico, ácido nicotínico, pantotenato de calcio, biotina, colina y minerales.', '1', '2026-11-04 23:32:38', '0', '0', NULL, 'Envío Gratis en Bahía Blanca + 20% OFF Transferencia');
