INSERT INTO `products` VALUES ('155', 'Pack Funcional Perro Chico (Vitalidad Old Prince 7.5kg + Treats Funcionales)', 'pack-funcional-perro-chico-old-prince-7-5kg-treats', 'CONVIVIA Packs', 'perro', 'adulto', 'pequeña', 'pack_funcional', '8.50', '48900.00', '44010.00', NULL, '20', 'https://nutricarepets.com.ar/wp-content/uploads/2024/07/Old-Prince-Perro-Adulto-Mordida-Pequena-7.5kg.png', NULL, 'Combo balanceado especialmente adaptado a perros de razas pequeñas. Croqueta de mordida pequeña Old Prince 7.5kg con ácidos grasos esenciales y golosinas funcionales para el cuidado del pelaje y vitalidad.', '1', '2026-11-03 20:06:30', '0', '1', NULL, 'Golosina Funcional de Regalo + Despacho Prioritario');
INSERT INTO `products` VALUES ('154', 'Pack Funcional Perro Grande (Nutrición Total Fawna 15kg + 2x Dental Snack)', 'pack-funcional-perro-grande-fawna-15kg-snacks', 'CONVIVIA Packs', 'perro', 'adulto', 'grande', 'pack_funcional', '16.50', '79900.00', '71910.00', NULL, '15', 'https://nutricarepets.com.ar/wp-content/uploads/2024/07/Fawna-Perro-Adulto-Mediano-y-Grande-15kg.png', NULL, 'Combo funcional diseñado para perros de razas grandes y gigantes. Incluye alimento premium Fawna 15kg con alta concentración de proteínas y doble snack dental Mon Ami para salud bucodental y articulaciones óptimas.', '1', '2026-11-03 20:06:30', '0', '1', NULL, 'Ahorro 20% en Combo + Dosificador de Alimento Gratis');
INSERT INTO `products` VALUES ('153', 'Nutricare Gatos Adultos 3 kg', 'nutricare-gatos-adultos-3kg', 'Nutricare', 'gato', 'adulto', 'todas', 'super_premium', '3.00', '18400.00', '16560.00', NULL, '25', 'https://nutricarepets.com.ar/wp-content/uploads/2023/09/bolsagato-2.png', 'https://nutricarepets.com.ar/wp-content/uploads/2023/08/gato.png', 'Alimento balanceado super premium para gatos adultos (enteros y castrados). Con 32% de proteína de alta calidad, taurina esencial, control de bolas de pelo mediante fibras especiales y magnesio controlado para cuidar la salud de las vías urinarias inferiores.\n\nBeneficios destacados:\n• Control de bolas de pelo (Hairball Control): Fibras vegetales insolubles y pulpa de remolacha que facilitan la eliminación natural de pelos a través del tracto digestivo.\n• Aporte de Taurina esencial: Aminoácido vital para el buen funcionamiento del músculo cardíaco, la agudeza visual y la salud reproductiva felina.\n• Salud del tracto urinario inferior: Magnesio rigurosamente controlado (máx. 0,1%) y bisulfato ácido de sodio para promover un pH urinario óptimo y prevenir cálculos.\n• Probióticos activos: Saccharomyces cerevisiae, Enterococcus faecium y Lactobacillus acidophilus que estabilizan la flora intestinal y optimizan la asimilación.\n• Reducción de olores fecales: Extracto de Yucca schidigera y zeolita purificada que disminuyen drásticamente el olor de la bandeja sanitaria.\n• Piel sana y pelo brillante: Ácidos grasos Omega 3 y 6 procedentes de aceite de pescado y vegetales para un pelaje suave y tupido.\n\nComposición centesimal:\n• Proteína bruta (mín.): 32%\n• Extracto etéreo (mín.): 17%\n• Fibra cruda (máx.): 4%\n• Minerales totales (máx.): 8%\n• Magnesio (máx.): 0,1%\n• Calcio: 1,20% (mín.) - 2,00% (máx.)\n• Fósforo: 1,00% (mín.) - 1,50% (máx.)\n• Humedad (máx.): 10%\n• Energía Metabolizable: 3.950 Kcal/kg de materia seca\n\nGuía de suministro diario sugerido:\n• Gatos 2 a 3 kg: 40 - 50 g (Castrados) | 50 - 75 g (Enteros)\n• Gatos 3 a 5 kg: 50 - 70 g (Castrados) | 70 - 100 g (Enteros)\n• Gatos 5 a 7 kg: 70 - 100 g (Castrados) | 100 - 130 g (Enteros)\n• Hembras gestantes (último tercio): 110 - 145 g / día\n• Hembras lactantes: 125 - 375 g / día según tamaño de camada\n*Una taza de té contiene aproximadamente 80 g de alimento.\n\nIngredientes completos:\nArroz; maíz; trigo; gluten de maíz; poroto de soja; pellet de afrechillo de trigo; harina de subproductos de pollo; expeller de soja; harina de pescado; harina de carne y hueso (bovina); grasa animal (bovina y/o aviar); hidrolizado de menudencias de aves, porcinas y vacunas; aceite de pescado (fuente de Omega 3). aceite vegetal (soja y/o girasol); levadura de cerveza; sal; pulpa de remolacha (fuente de fructo-oligosacáridos); bisulfato ácido de sodio; zeolita; fibra cruda insoluble; carbonato de calcio; cloruro de potasio; metionina; sorbato de potasio; propionato de calcio; manano-oligosacáridos; extracto de Yucca shidigera; taurina; BHT; BHA; extracto de romero; tocoferoles naturales; aceites esenciales (orégano–romero-tomillo); arginina; levadura (Sacharomyces cerevisiae), Enterococcus faecium, Lactobacillus acidophilus; minerales: zinc (como óxido y/o sulfato de zinc), hierro (como sulfato ferroso), cobre (como sulfato de cobre), manganeso (como óxido y/o sulfato de manganeso), yodo (como yodato de calcio), selenio (como selenito de sodio); vitaminas: A, D3, E, K, B1, B2, B6, B12, niacina; ácido fólico, ácido pantoténico; biotina, colina.', '0', '2026-11-03 13:09:56', '0', '0', NULL, NULL);
