INSERT INTO `products` VALUES ('149', 'Nutricare Perros Adultos Razas Pequeñas (Mordida Pequeña) 3 kg', 'nutricare-perros-adultos-mordida-pequena-3kg', 'Nutricare', 'perro', 'adulto', 'pequeña', 'super_premium', '3.00', '15400.00', '13860.00', NULL, '25', 'https://nutricarepets.com.ar/wp-content/uploads/2023/09/adulto-2-1.png', 'https://nutricarepets.com.ar/wp-content/uploads/2023/08/perroadulto.png', 'Alimento balanceado super premium para perros adultos de razas pequeñas con croqueta de tamaño reducido y fácil masticación (\"Mordida Pequeña\"). Especialmente formulado para satisfacer el metabolismo acelerado de perros pequeños, enriquecido con probióticos activos, antioxidantes naturales y sin colorantes artificiales.\n\nBeneficios destacados:\n• Croqueta pequeña adaptada: Textura y tamaño ideal para mandíbulas reducidas que favorece la masticación y previene la formación de placa bacteriana.\n• Probióticos activos: Con Saccharomyces cerevisiae, Enterococcus faecium y Lactobacillus acidophilus para proteger la barrera intestinal y optimizar la digestión de estómagos pequeños y sensibles.\n• Sin colorantes con antioxidantes naturales: Libre de colorantes artificiales, conservado naturalmente con tocoferoles y extracto de romero.\n• Salud de piel y pelaje: Ácidos grasos Omega 3 y 6 provenientes de aceite de pescado para un pelaje radiante y piel sana.\n• Alta concentración nutricional y sabor exquisito: Provee la densidad energética necesaria con un sabor irresistible.\n\nComposición centesimal:\n• Proteína bruta (mín.): 24%\n• Extracto etéreo (mín.): 14%\n• Fibra cruda (máx.): 4%\n• Minerales totales (máx.): 8%\n• Calcio: 0,95% (mín.) - 2,00% (máx.)\n• Fósforo: 0,75% (mín.) - 1,50% (máx.)\n• Humedad (máx.): 10%\n• Energía Metabolizable: 3.800 Kcal/kg de materia seca\n\nGuía de suministro diario sugerido:\n• Perros Miniatura (hasta 5 kg): 50 - 120 g / día\n• Perros Pequeños (5 a 10 kg): 120 - 200 g / día\n• Perros Medianos (10 a 15 kg): 200 - 280 g / día\n*Una taza de té contiene aproximadamente 80 g de alimento.\n\nIngredientes completos:\nArroz; maíz; trigo; gluten de maíz; harina de subproductos de pollo; expeller de soja; harina de carne y hueso bovina; pellet de afrechillo de trigo; poroto de soja; sorgo; grasa animal (bovina y/o aviar); aceite vegetal (girasol y/o soja); aceite de pescado (fuente de Omega 3); saborizante: hidrolizado de menudencias vacunas, porcinas y aviares; lino; levadura de cerveza; sal; zeolita; carbonato de calcio; sorbato de potasio; cloruro de potasio; pulpa de remolacha (fuente de fructo-oligosacáridos); manano-oligosacáridos; extracto de Yucca shidigera; metionina; BHT; BHA; extracto de romero; tocoferoles naturales (alfa-beta-gama-delta), aceites esenciales (Orégano-Romero-Tomillo); levaduras Saccharomyces cerevisiae, Enterococcus faecium y Lactobacillus acidophilus; minerales: hierro (como sulfato ferroso), manganeso (como óxido de manganeso), cobre (como sulfato de cobre), zinc (como sulfato de zinc), yodo (como yodato de calcio), selenio (como selenito de sodio); vitaminas: A, D3, E, K, B1, B2, B6, B12, ácido fólico, ácido pantoténico, niacina, biotina, colina.', '0', '2026-11-03 13:09:56', '0', '0', NULL, NULL);
