INSERT INTO `products` VALUES ('147', 'Nutricare Perros Adultos Razas Medianas y Grandes (Mordida Grande) 3 kg', 'nutricare-perros-adultos-mordida-grande-3kg', 'Nutricare', 'perro', 'adulto', 'grande', 'super_premium', '3.00', '15400.00', '13860.00', NULL, '25', 'https://nutricarepets.com.ar/wp-content/uploads/2023/09/adulto-2-1.png', 'https://nutricarepets.com.ar/wp-content/uploads/2023/08/perroadulto.png', 'Alimento balanceado super premium para perros adultos de razas medianas y grandes con croqueta de tamaño adaptado (\"Mordida Grande\"). Formulado con probióticos activos, sin colorantes artificiales y con antioxidantes naturales de origen botánico para una digestión superior, heces firmes y máxima vitalidad.\n\nBeneficios destacados:\n• Probióticos activos: Con levaduras seleccionadas (Saccharomyces cerevisiae, Enterococcus faecium y Lactobacillus acidophilus) que modulan la flora intestinal benéfica y refuerzan las defensas naturales.\n• Sin colorantes con antioxidantes naturales: Elaborado exclusivamente con el color noble de sus ingredientes y preservado naturalmente con tocoferoles mixtos, extracto de romero y aceites esenciales.\n• Salud intestinal y digestibilidad superior: Materias primas de alto valor biológico que optimizan la asimilación de nutrientes, complementadas con extracto de Yucca schidigera y zeolita para reducir olores fecales.\n• Piel saludable y manto brillante: Concentración balanceada de ácidos grasos esenciales Omega 3 y Omega 6 procedentes de aceite de pescado puro y aceites vegetales.\n• Palatabilidad insuperable: Fórmula irresistible elaborada para satisfacer el apetito de los caninos más exigentes.\n\nComposición centesimal:\n• Proteína bruta (mín.): 24%\n• Extracto etéreo (mín.): 14%\n• Fibra cruda (máx.): 4%\n• Minerales totales (máx.): 8%\n• Calcio: 0,95% (mín.) - 2,00% (máx.)\n• Fósforo: 0,75% (mín.) - 1,50% (máx.)\n• Humedad (máx.): 10%\n• Energía Metabolizable: 3.800 Kcal/kg de materia seca\n\nGuía de suministro diario sugerido:\n• Perros Miniatura (hasta 5 kg): 50 - 120 g / día\n• Perros Pequeños (5 a 10 kg): 120 - 200 g / día\n• Perros Medianos (10 a 25 kg): 200 - 400 g / día\n• Perros Grandes (25 a 45 kg): 400 - 620 g / día\n*Una taza de té contiene aproximadamente 80 g de alimento.\n\nIngredientes completos:\nArroz; maíz; trigo; gluten de maíz; harina de subproductos de pollo; expeller de soja; harina de carne y hueso bovina; pellet de afrechillo de trigo; poroto de soja; sorgo; grasa animal (bovina y/o aviar); aceite vegetal (girasol y/o soja); aceite de pescado (fuente de Omega 3); saborizante: hidrolizado de menudencias vacunas, porcinas y aviares; lino; levadura de cerveza; sal; zeolita; carbonato de calcio; sorbato de potasio; cloruro de potasio; pulpa de remolacha (fuente de fructo-oligosacáridos); manano-oligosacáridos; extracto de Yucca shidigera; metionina; BHT; BHA; extracto de romero; tocoferoles naturales (alfa-beta-gama-delta), aceites esenciales (Orégano-Romero-Tomillo); levaduras Saccharomyces cerevisiae, Enterococcus faecium y Lactobacillus acidophilus; minerales: hierro (como sulfato ferroso), manganeso (como óxido de manganeso), cobre (como sulfato de cobre), zinc (como sulfato de zinc), yodo (como yodato de calcio), selenio (como selenito de sodio); vitaminas: A, D3, E, K, B1, B2, B6, B12, ácido fólico, ácido pantoténico, niacina, biotina, colina.', '0', '2026-11-03 13:09:56', '0', '0', NULL, NULL);
INSERT INTO `products` VALUES ('146', 'Nutricare Perros Adultos Razas Medianas y Grandes (Mordida Grande) 7.5 kg', 'nutricare-perros-adultos-mordida-grande-7-5kg', 'Nutricare', 'perro', 'adulto', 'grande', 'super_premium', '7.50', '27900.00', '25110.00', NULL, '20', 'https://nutricarepets.com.ar/wp-content/uploads/2023/09/adulto-2-1.png', 'https://nutricarepets.com.ar/wp-content/uploads/2023/08/perroadulto.png', 'Alimento balanceado super premium para perros adultos de razas medianas y grandes con croqueta de tamaño adaptado (\"Mordida Grande\"). Formulado con probióticos activos, sin colorantes artificiales y con antioxidantes naturales de origen botánico para una digestión superior, heces firmes y máxima vitalidad.\n\nBeneficios destacados:\n• Probióticos activos: Con levaduras seleccionadas (Saccharomyces cerevisiae, Enterococcus faecium y Lactobacillus acidophilus) que modulan la flora intestinal benéfica y refuerzan las defensas naturales.\n• Sin colorantes con antioxidantes naturales: Elaborado exclusivamente con el color noble de sus ingredientes y preservado naturalmente con tocoferoles mixtos, extracto de romero y aceites esenciales.\n• Salud intestinal y digestibilidad superior: Materias primas de alto valor biológico que optimizan la asimilación de nutrientes, complementadas con extracto de Yucca schidigera y zeolita para reducir olores fecales.\n• Piel saludable y manto brillante: Concentración balanceada de ácidos grasos esenciales Omega 3 y Omega 6 procedentes de aceite de pescado puro y aceites vegetales.\n• Palatabilidad insuperable: Fórmula irresistible elaborada para satisfacer el apetito de los caninos más exigentes.\n\nComposición centesimal:\n• Proteína bruta (mín.): 24%\n• Extracto etéreo (mín.): 14%\n• Fibra cruda (máx.): 4%\n• Minerales totales (máx.): 8%\n• Calcio: 0,95% (mín.) - 2,00% (máx.)\n• Fósforo: 0,75% (mín.) - 1,50% (máx.)\n• Humedad (máx.): 10%\n• Energía Metabolizable: 3.800 Kcal/kg de materia seca\n\nGuía de suministro diario sug