INSERT INTO `products` VALUES ('120', 'Snack Saludable Gato Chicken 50G', 'mon-ami-snack-saludable-gato-chicken-50g', 'Mon Ami', 'gato', 'todas', 'todas', 'snacks', '0.05', '3196.63', '2876.97', NULL, '15', 'https://acdn-us.mitiendanube.com/stores/006/071/448/products/list_snack-gato-chiken-60d90f12417afc5fea17920768068132-1024-1024.webp', 'https://acdn-us.mitiendanube.com/stores/006/071/448/products/list_snack-gato-chiken-2-e9b3d438f47e517f7817920768265086-1024-1024.webp', 'Mon Ami Cat Treat es un snack natural y saludable para gatos de todas las edades. Elaborado con ingredientes cárnicos de alta calidad, sin cereales ni subproductos, y con fórmula clean label. Rico en proteínas animales y colágeno natural, ideal como premio o refuerzo positivo. Contiene carne fresca como primer ingrediente y un 55% de proteína, respetando la naturaleza carnívora del gato.   Libre de maiz y soja Snacks saludables Con carne fresca de pollo Ingredientes naturales   Contenido: 50 gr', '0', '2026-11-03 10:03:29', '0', '0', NULL, NULL);
