INSERT INTO `products` VALUES ('118', 'Alimento Urinary Care Cat 6 kg', 'mon-ami-alimento-urinary-care-cat-6-kg', 'Mon Ami', 'gato', 'adulto', 'todas', 'veterinario', '6.00', '153144.75', '137830.28', NULL, '15', 'https://acdn-us.mitiendanube.com/stores/006/071/448/products/6kg-urinary-cat-frente-c266d6bd3cc7f69a7117920737803828-1024-1024.webp', 'https://acdn-us.mitiendanube.com/stores/006/071/448/products/listing-enriquecido-urinary-care-cat-6-539f86c9f168e9f1ab17920736156102-1024-1024.webp', 'Alimento funcional para gatos adultos con predisposición a trastornos de las vías urinarias bajas  Algunos gatos pueden presentar predisposición a trastornos del tracto urinario inferior, incluyendo la formación de cristales urinarios y la cistitis idiopática felina. Diversos factores, como el estrés, la baja ingesta de agua, el sobrepeso y la producción de orinas concentradas, pueden aumentar el riesgo de su aparición. Una receta para gatos adultos que contribuye a mantener la salud del tracto urinario inferior Su receta con  ingredientes funcionales contribuye a la formación de una orina más diluida, un pH óptimo (6,2–6,5) y un adecuado balance mineral, ayudando a reducir el riesgo de formación de cristales. Control del pH urinario Mayor dilución urinaria  Balance mineral Condroitín sulfato Ácidos grasos Omega 3   Composición centesimal Proteína bruta: 33% Extracto etéreo: 15% Fibra cruda: 3% Minerales totales: 7% Humedad: 10% Calcio: 0,68–0,75% Fósforo: 0,55–0,62% Energía metabolizable: 3940 kcal/kg sobre materia seca y 3510 kcal/kg tal cual.   Ingredientes Carne de pollo, arroz, salmón rosado molido, albúmina de huevo, aceite de pescado, hidrolizado de menudencias aviares, levadura de cerveza, huevo en polvo, pulpa de remolacha, sal, aceite de girasol, celulosa en polvo, ácido propiónico, propionato de amonio, ácido sórbico, glucosamina, sulfato de condroitina, DL-metionina, pared celular de levadura, taurina, antioxidantes: aceite vegetal, tocoferoles mezclados, lecitina y extracto de romero, L-carnitina, extracto de Yucca schidigera, sulfato ferroso, sulfato de zinc, vitamina E, niacina, selenito de sodio, sulfato de manganeso, sulfato de cobre, vitamina B1 (tiamina), pantotenato de calcio, vitamina B2 (riboflavina), vitamina B6 (piridoxina), biotina, vitaminas A y D3, vitamina B12, ácido fólico, iodato de calcio y vitamina K3.  ', '0', '2026-11-03 10:03:26', '0', '0', NULL, NULL);
