INSERT INTO `products` VALUES ('74', 'Alimento Obesity Management Dog 1.4 Kg', 'mon-ami-alimento-obesity-management-dog-1-4-kg', 'Mon Ami', 'perro', 'adulto', 'todas', 'veterinario', '1.40', '27395.15', '24655.64', NULL, '15', 'https://acdn-us.mitiendanube.com/stores/006/071/448/products/listing-enriquecido-obesity-management-dog-1-c6be578c46239979de17920750467608-1024-1024.webp', 'https://acdn-us.mitiendanube.com/stores/006/071/448/products/listing-enriquecido-obesity-management-dog-6-cc0cf8892db9ac7c7f17920750684616-1024-1024.webp', 'Alimento funcional para perros con sobrepeso u obesidad, orientado al descenso de peso y al mantenimiento de la masa muscular.  Su receta combina proteína animal de alta calidad, aporte calórico controlado, fibras funcionales y nutracéuticos que actúan sobre distintos mecanismos metabólicos involucrados en la obesidad. Carne de pollo como primer ingrediente Con conservantes naturales  Con salmón rosado  Con L- carnitina  Con fibras funcionales  Con Omega 3 (EPA + DHA) del Salmón y aceite de pescado   El sobrepeso y la obesidad pueden afectar la calidad de vida de los perros, limitando su movilidad y aumentando el riesgo de desarrollar diversos trastornos de salud. Este alimento funcional está formulado para acompañar programas de control de peso, ayudando a mantener la masa muscular y favoreciendo una condición corporal saludable.   Mon Ami Funcional Obesity Managment Dog Preserva la masa muscular Favorece la saciedad Estimula la utilización de grasas como fuente de energía Modula la inflamación asociada al exceso de tejido adiposo Acompaña el equilibrio digestivo y la microbiota intestinal Favorece un descenso de peso saludable y sostenible, mejorando la calidad de vida y el bienestar integral del perro.   Composición centesimal Proteína bruta: 30% Extracto etéreo (grasa): 7% Fibra cruda: 4% L-carnitina: 0,07% (700 ppm) Energía metabolizable: 3100 kcal/kg   Ingredientes Carne de pollo, arroz, salmón rosado molido, pulpa de remolacha, albúmina de huevo, aceite de pescado, hidrolizado de menudencias aviares, almidón de mandioca, levadura de cerveza, celulosa en polvo, zeolita, sal, pared celular de levadura, taurina, ácido propiónico, propionato de amonio, ácido ascórbico, L-carnitina, extracto de yucca schidigera, antioxidantes (aceite vegetal, tocoferoles mezclados, lecitina y extracto de romero), carbonato de calcio, sulfato de zinc, sulfato ferroso, vitamina E, sulfato de cobre, niacina, selenito de sodio, pantotenato de calcio, vitaminas A y D3, óxido manganoso, vitamina B2 (riboflavina), vitamina K3, vitamina B12, vitamina B1 (tiamina), iodato de calcio, biotina, vitamina B6 (piridoxina), ácido fólico.', '0', '2026-11-03 10:02:29', '0', '0', NULL, NULL);
INSERT INTO `products` VALUES ('73', 'Alimento Obesity Management Dog 6 Kg', 'mon-ami-alimento-obesity-management-dog-6-kg', 'Mon Ami', 'perro', 'adulto', 'todas', 'veterinario', '1.40', '28837.00', '25953.30', NULL, '12', 'https://acdn-us.mitiendanube.com/stores/006/071/448/products/obesity-6-frente-a30ec4803e94690ae117817119284873-1024-1024.webp', 'https://acdn-us.mitiendanube.com/stores/006/071/448/products/listing-enriquecido-obesity-management-dog-6-fe9b5b47ff8fd23b6717920749635891-1024-1024.webp', 'Obesity Management Dog 1.4 kg, alimento para perros formulado para acompañar el control de peso. Una opción para una alimentación equilibrada.', '0', '2026-11-03 10:02:28', '0', '0', NULL, NULL);
INSERT INTO `products` VALUES ('72', 'Alimento Hypoallergenic Dog 1.4 Kg', 'mon-ami-alimento-hypoallergenic-dog-1-4-kg', 'Mon Ami', 'perro', 'adulto', 'todas', 'veterinario', '1.40', '24954.60', '22459.14', NULL, '15', 'https://acdn-us.mitiendanube.com/stores/006/071/448/products/listing-enriquecido-alimento-hypoallergenic-dog-1-7d9f180dd27c1297d117920771659001-1024-1024.webp', 'https://acdn-us.mitiendanube.com/stores/006/071/448/products/listing-enriquecido-alimento-hypoallergenic-dog-6-6d134e6a9616e9256817920771857924-1024-1024.webp', 'Alimento funcional especialmente pensado para perros con tendencia a alergias o intolerancias alimentarias. Algunos perros pueden presentar reacciones adversas a ciertos nutrientes, con signos digestivos y/o cutáneos. El alimento funcional busca minimizar el riesgo de alergias, favorecer la tolerancia digestiva y contribuir a la salud de la piel y el pelo. Su receta con proteína hidrolizada de soja como fuente proteica es altamente digestible y orientada a reducir la respuesta inmunológica  Proteína hidrolizada de soja: Reducción del riesgo de reacciones alérgicas Con conservantes naturales  Elevada digestibilidad: La proteína de soja hidrolizada aporta un perfil aminoacídico completo y una digestibilidad superior al 85% Soporte cutáneo: Los ácidos grasos Omega 3 (EPA y DHA) contribuyen al mantenimiento de la salud cutánea Indicada para dietas de eliminación: utilizada en protocolos nutricionales veterinarios   Ingredientes Proteína de soja hidrolizada, arroz, hidrolizado de hígado de pollo, fécula de papa, pulpa de remolacha, avena, aceite de pescado, hidrolizado proteico de pollo, levadura de cerveza, zeolita, sal, paredes de levadura, ácido propiónico, propionato de amonio, ácido sórbico, glutamina, extracto de yucca schidigera, antioxidantes (aceite vegetal, tocoferoles mezclados, lecitina y extracto de romero), carbonato de calcio, sulfato de zinc, sulfato ferroso, vitamina E, sulfato de cobre, niacina, selenito de sodio, pantotenato de calcio, vitaminas A y D3, óxido manganoso, vitamina B2 (riboflavina), vitamina K3, vitamina B12, vitamina B1 (tiamina), iodato de calcio, biotina, vitamina B6 (piridoxina), ácido fólico.   Composición centesimal Proteína bruta: 24% Extracto etéreo (grasa): 12% Fibra cruda: 3% Cenizas: 8% Humedad: 10% Calcio: 0,6%–1,2% Fósforo: 0,5%–1% Energía metabolizable: 3763 kcal/kg sobre MS.', '0', '2026-11-03 10:02:27', '0', '0', NULL, NULL);
INSERT INTO `products` VALUES ('71', 'Alimento Hypoallergenic Dog 6 Kg', 'mon-ami-alimento-hypoallergenic-dog-6-kg', 'Mon Ami', 'perro', 'adulto', 'todas', 'veterinario', '6.00', '26268.00', '23641.20', NULL, '11', 'https://acdn-us.mitiendanube.com/stores/006/071/448/products/hypo-6k-frente-7922d23937a212310317817118091523-1024-1024.webp', 'https://acdn-us.mitiendanube.com/stores/006/071/448/products/listing-enriquecido-alimento-hypoallergenic-dog-6-a8e19425c3df4920b817920773254772-1024-1024.webp', 'Hypoallergenic Dog 1.4 kg, alimento hipoalergénico para perros con necesidades nutricionales específicas. Ideal para acompañar una alimentación equilibrada.', '0', '2026-11-03 10:02:26', '0', '0', NULL, NULL);
INSERT INTO `products` VALUES ('70', 'Alimento Natural de Pollo 12 Kg.', 'mon-ami-alimento-natural-de-pollo-12-kg', 'Mon Ami', 'perro', 'adulto', 'todas', 'premium', '12.00', '78823.53', '70941.18', NULL, '15', 'https://acdn-us.mitiendanube.com/stores/006/071/448/products/7-798320-833431-pollo-12k-1-93dba1ed2c06c895ba17447349051918-1024-1024.webp', 'https://acdn-us.mitiendanube.com/stores/006/071/448/products/7-798320-833431-pollo-12k-6-97e15dc04ebb6a2bef17447349048810-1024-1024.webp', 'Elaborada con carne fresca de pollo, esta nueva presentación de nuestro Alimento Super Premium Natural ahora está disponible en una de las proteínas favoritas de los perros. Con conservantes naturales, esta receta está especialmente indicada para perros adultos. Con 80% de proteínas de origen animal, 100% de ingredientes naturales, probióticos y prebióticos, Natural de Pollo ofrece una excelente calidad proteica y digestibilidad para cuidar la salud intestinal de nuestros mejores amigos. Para perros adultos.    1er ingrediente carne fresca de pollo  80% proteinas de origen animal  Ingredientes 100% naturales  Probioticos para la salud digestiva  Receta con acidos grasos que benefician a la piel y el pelo Contenido: 12 Kg.', '0', '2026-11-03 10:02:24', '0', '0', NULL, NULL);
INSERT INTO `products` VALUES ('69', 'Alimento Natural de Cordero 7,5 Kg', 'mon-ami-alimento-natural-de-cordero-7-5-kg', 'Mon Ami', 'perro', 'adulto', 'todas', 'premium', '7.50', '62950.12', '56655.11', NULL, '15', 'https://acdn-us.mitiendanube.com/stores/006/071/448/products/7-798320-833356-cordero7-5k-1-e28cdad06dfd28ce7317447347221346-1024-1024.webp', 'https://acdn-us.mitiendanube.com/stores/006/071/448/products/7-798320-833356-cordero7-5k-6-5df7d0937c276b5dd817447347223344-1024-1024.webp', 'Nutrición completa con carne fresca de cordero e ingredientes 100% naturales Nuestra receta con proteínas noveles es ideal para perros adultos que presentan alergias o sensibilidades. Elaborada con ingredientes naturales, sin conservantes artificiales y con el sello de calidad Mon Ami, ofrece una nutrición completa, sabrosa y fácil de digerir. Un alimento pensado para cuidar su salud y bienestar todos los días. Para perros adultos.  Ingredientes naturales Menor riesgo de alergias Probióticos para la salud digestiva Elaboradas con carne fresca  Contenido: 7,5 Kg', '0', '2026-11-03 10:02:23', '0', '0', NULL, NULL);
