INSERT INTO `products` VALUES ('59', 'Maintenance Criadores Gato Urinario', 'maintenance-criadores-gato-urinario-7kg', 'Maintenance Criadores', 'gato', 'adulto', 'todas', 'super_premium', '7.50', '28600.00', '25740.00', NULL, '20', 'https://baires-sa.com.ar/img_productos/criadoresgatourinario.png', 'https://baires-sa.com.ar/img_productos/Composision centimal Gato Urinario Criadores.png', 'Alimento balanceado profesional formulado para el manejo y cuidado del tracto urinario felino. Ayuda a disolver y prevenir cálculos mediante un balance mineral preciso y control riguroso de pH.\n\nBeneficios destacados:\n• Control de acidez urinaria\n• Bajo tenor de fósforo y magnesio\n• Proteínas de pescado y pollo altamente digestibles\n\nIngredientes completos:\nHarina de pescado, harina de pollo, harina de carne vacuna, arroz, gluten de maíz, arveja, aceite de pollo, aceite de salmon (fuente de omega 3 y 6), huevo en polvo, plasma bovino en polvo, pulpa de remolacha (fuente de fructo-oligo-sacaridos-FOS), levadura de cerveza, hidrolizado proteico de menudencias porcinas, fibra insoluble (celulosa), zeolita, carbonato de calcio, extracto de yucca schidigera, sal, acidificante en polvo (bisulfato ácido de sodio), propionato de calcio, ácido propionico, lisina, taurina, metionina, ácido cítrico, tocoferoles, extracto de romero, núcleo vitamínico-mineral; vitaminas A, D3, E, K, B1, B2, B6, B12, ácido nicotínico, pantotenato de calcio, ácido fólico, colina, biotina, minerales: zinc (oxido de zinc, zinc quelatado), carbonato de calcio, hierro (sulfato ferroso), manganeso (oxido manganeso), cobre (cobre quelatado), yodo (iodato de calcio), selenio (levadura de selenio).', '0', '2026-11-02 21:58:50', '0', '0', NULL, NULL);
